pub struct Config {
    pub host: String,
    pub port: u16,
}

pub fn load_config() -> Config {
    let contents = std::fs::read_to_string("config.json")
        .expect("failed to read config.json");

    let host = json_string_value(&contents, "host")
        .expect("config.json must contain a string `host` field");
    let port = json_number_value(&contents, "port")
        .and_then(|value| value.parse().ok())
        .expect("config.json must contain a valid `port` field");

    Config { host, port }
}

fn json_string_value(json: &str, key: &str) -> Option<String> {
    let value = json_value(json, key)?;
    let value = value.strip_prefix('\"')?;
    let end = value.find('\"')?;
    Some(value[..end].to_string())
}

fn json_number_value<'a>(json: &'a str, key: &str) -> Option<&'a str> {
    let value = json_value(json, key)?;
    let end = value
        .find(|character: char| !character.is_ascii_digit())
        .unwrap_or(value.len());
    Some(&value[..end])
}

fn json_value<'a>(json: &'a str, key: &str) -> Option<&'a str> {
    let key = format!("\"{key}\"");
    let key_start = json.find(&key)? + key.len();
    let value_start = json[key_start..].find(':')? + key_start + 1;
    Some(json[value_start..].trim_start())
}
